  const midY = (o2.y1 + o2.y2) / 2;
  const ang = Math.atan2(o2.y2 - o2.y1, o2.x2 - o2.x1);
  const vertical = Math.abs(Math.abs(ang) - Math.PI / 2) < Math.PI / 4;
  const posAbove = vertical ? ang > 0 ? "right" : "left" : "above";
  const posBelow = vertical ? ang > 0 ? "left" : "right" : "below";
  if (o2.text.trim() !== "") {
    lines.push(
      `\\node[${posAbove}, font=\\small, text=${o2.color}] at (${fmt(midX)},${fmt(midY)}) {${escapeNodeText(o2.text)}};`
    );
  }
  if (o2.textBelow.trim() !== "") {
    lines.push(
      `\\node[${posBelow}, font=\\small, text=${o2.color}] at (${fmt(midX)},${fmt(midY)}) {${escapeNodeText(o2.textBelow)}};`
    );
  }
