// src/utils/geometry.ts
function cmToLocal(xCm, yCm, graphH, info) {
  return {
    x: (xCm - info.contentMinX + CANVAS_MARGIN) * info.ptPerCm,
    y: (info.contentMaxY + CANVAS_MARGIN - yCm) * info.ptPerCm
  };
}
function localToCm(lx, ly, graphH, info) {
  return {
    x: lx / info.ptPerCm + info.contentMinX - CANVAS_MARGIN,
    y: info.contentMaxY + CANVAS_MARGIN - ly / info.ptPerCm
  };
}
function eventToLocal(e2, wrap, info) {
  const r2 = wrap.getBoundingClientRect();
  return {
    x: (e2.clientX - r2.left) / info.zoom,
    y: (e2.clientY - r2.top) / info.zoom
  };
}

